const $=id=>document.getElementById(id),M=StudyMath,fmt=n=>Math.abs(n)<.0005?'0':Number(n.toFixed(2)).toString(),math=s=>'<math xmlns="http://www.w3.org/1998/Math/MathML"><mrow>'+s+'</mrow></math>',mi=(s,key=s)=>symbolMarkup(s,key),mn=n=>n<-.0005?mo('−')+'<mn>'+fmt(-n)+'</mn>':'<mn>'+fmt(n)+'</mn>',mo=s=>'<mo'+(['(',')'].includes(s)?' stretchy="false"':'')+'>'+s+'</mo>',sub=(s,a)=>symbolMarkup(s+'_'+a,s+'_'+a,'<msub><mi>'+s+'</mi><mi>'+a+'</mi></msub>'),fraction=(a,b)=>'<mfrac><mrow>'+a+'</mrow><mrow>'+b+'</mrow></mfrac>';
let state={a:120,alpha:30,b:90,beta:120};let practice={a:100,alpha:0,b:100,beta:90},hintLevel=0,solved=false;
function showView(name){if(window.examInProgress&&name!=='assessment')return;document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==name);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===name));document.querySelectorAll('.course button[data-view]').forEach(b=>{const active=b.dataset.view===name;b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false');});if(name==='reference')renderReference();window.StudyExperience?.activate(name);document.querySelectorAll('.view:not([hidden]) svg').forEach(svg=>GraphScales.layout(svg));}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>showView(b.dataset.view));document.querySelectorAll('.course button[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));$('toPractice').onclick=()=>showView('practice');
function symbolMarkup(label,key,body){
 const info=Learning.symbols[key];
 if(!info)return '<mi>'+M.esc(label)+'</mi>';
 return '<mrow class="symbol-token" data-symbol="'+key+'" tabindex="0" role="button" aria-label="Explain '+M.esc(info[0])+'">'+(body||'<mi>'+M.esc(label)+'</mi>')+'</mrow>';
}
function vector(label,key){return '<mstyle mathvariant="bold">'+mi(label,key)+'</mstyle>';}
function taggedVector(label,suffix,key){return symbolMarkup(label+suffix,key,'<msub><mstyle mathvariant="bold"><mi>'+label+'</mi></mstyle><mtext>'+suffix+'</mtext></msub>');}
function solution(s){
 const r=M.resultant(s.a,s.alpha,s.b,s.beta);
 const component=(force,axis,value,angle,result)=>math(sub(force,axis)+mo('=')+mi(force)+mi(axis==='x'?'cos':'sin')+mi(force==='A'?'α':'β',force==='A'?'alpha':'beta')+mo('=')+mn(value)+mi(axis==='x'?'cos':'sin')+mo('(')+mn(angle)+mo('°')+mo(')')+mo('=')+mn(result)+mi('N'));
 return `<div class="symbol-help">Tap an <strong>underlined symbol</strong> to see what it means in this equation.</div>
 <div class="step" data-equation="Resolve each force"><div class="step-title"><span>01</span> Resolve each force</div><div class="math">${component('A','x',s.a,s.alpha,r.ax)}${component('A','y',s.a,s.alpha,r.ay)}${component('B','x',s.b,s.beta,r.bx)}${component('B','y',s.b,s.beta,r.by)}</div><p><strong>Use when:</strong> each force’s <strong>magnitude and angle from +x</strong> are known. Cosine gives x; sine gives y. Here <strong>α = ${fmt(s.alpha)}°</strong> belongs to A and <strong>β = ${fmt(s.beta)}°</strong> belongs to B.</p></div>
 <div class="step" data-equation="Add signed components"><div class="step-title"><span>02</span> Add signed components</div><div class="math">${math(sub('R','x')+mo('=')+sub('A','x')+mo('+')+sub('B','x')+mo('=')+mn(r.ax)+mo('+')+mo('(')+mn(r.bx)+mo(')')+mo('=')+mn(r.x)+mi('N'))}${math(sub('R','y')+mo('=')+sub('A','y')+mo('+')+sub('B','y')+mo('=')+mn(r.ay)+mo('+')+mo('(')+mn(r.by)+mo(')')+mo('=')+mn(r.y)+mi('N'))}</div><p><strong>Need:</strong> all signed components in the <strong>same coordinate system</strong>. Negative components point along the negative axis. <strong>Keep their signs.</strong></p></div>
 <div class="step" data-equation="Find the resultant magnitude"><div class="step-title"><span>03</span> Find the magnitude</div><div class="math">${math(mi('R')+mo('=')+'<msqrt><mrow><msup>'+sub('R','x')+mn(2)+'</msup>'+mo('+')+'<msup>'+sub('R','y')+mn(2)+'</msup></mrow></msqrt>'+mo('=')+mn(r.magnitude)+mi('N'))}</div><p><strong>Need:</strong> Rₓ and Rᵧ after adding forces. The axes are <strong>perpendicular</strong>, so use the Pythagorean theorem. This gives <strong>magnitude only</strong>.</p></div>
 <div class="step" data-equation="Find the 2D resultant direction"><div class="step-title"><span>04</span> Find the direction</div><div class="math">${r.angle===null?'Direction undefined: the resultant is zero.':math(mi('θ','thetaResult')+mo('=')+mi('atan2')+mo('(')+sub('R','y')+mo(',')+sub('R','x')+mo(')')+mo('=')+mn(r.angle)+mo('°'))}</div><p><strong>θ is measured from +x to the resultant</strong>, counterclockwise. Need both <strong>signed components</strong> and a <strong>nonzero resultant</strong>. On a TI-84, use tan⁻¹(Rᵧ/Rₓ) and <strong>adjust the quadrant</strong>; handle Rₓ = 0 separately.</p></div>`;
}
function diagram(s,interactive=true){const r=M.resultant(s.a,s.alpha,s.b,s.beta),fitScale=160/Math.max(s.a,s.b,r.magnitude,1),frame=interactive?GraphScales.frame('diagram','xy',{scale:fitScale,offsetX:250,offsetY:285,extent:Math.max(s.a,s.b,r.magnitude,1)*1.1},render,'N'):{scale:fitScale,extent:Math.max(s.a,s.b,r.magnitude,1)*1.1},scale=frame.scale,ox=250,oy=285,p=(x,y)=>[ox+x*scale,oy-y*scale],A=p(r.ax,r.ay),B=p(r.bx,r.by),R=p(r.x,r.y);let out='<defs><pattern id="grid" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0V25" fill="none" stroke="#253040" stroke-width=".6"/></pattern>';for(const [id,c] of [['a','#8cbcff'],['b','#efbd77'],['r','#b4f178']])out+=`<marker id="arrow${id}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="${c}"/></marker>`;out+='</defs><rect width="600" height="440" fill="url(#grid)"/>';
out+=GraphScales.axesSVG('xy',q=>p(q[0],q[1]),frame.extent,'N',440);
if($('parallelogram').checked||!interactive)out+=`<path d="M${A}L${R}L${B}" fill="none" stroke="#566b68" stroke-width="1.5" stroke-dasharray="6 6"/>`;
if($('components').checked&&interactive)out+=`<path d="M${ox} ${oy}L${R[0]} ${oy}L${R}" fill="none" stroke="#b4f178" opacity=".4" stroke-dasharray="4 5"/>`;
for(const [id,end,c,label] of [['r',R,'#b4f178','R'],['a',A,'#8cbcff','A'],['b',B,'#efbd77','B']]){out+=`<line x1="${ox}" y1="${oy}" x2="${end[0]}" y2="${end[1]}" stroke="${c}" stroke-width="${id==='r'?3:2.5}" marker-end="url(#arrow${id})"/><text x="${end[0]+12}" y="${end[1]-10}" fill="${c}" font-size="15">${label}</text>`;if(id!=='r'&&interactive)out+=`<circle data-force="${id}" cx="${end[0]}" cy="${end[1]}" r="15" fill="${c}" fill-opacity=".12" stroke="${c}" stroke-opacity=".6" style="cursor:grab"/>`;}
out+=`<circle cx="${ox}" cy="${oy}" r="5" fill="#e7edf5"/><text x="${ox-20}" y="${oy+22}" fill="#94a3b8">O</text>`;return {out,scale,ox,oy};}
function render(){const d=diagram(state);GraphScales.paint($('diagram'),d.out);$('diagram').dataset.scale=d.scale;const r=M.resultant(state.a,state.alpha,state.b,state.beta);$('steps').innerHTML=solution(state);$('resultSummary').innerHTML=`<div><small>RESULTANT MAGNITUDE</small>${fmt(r.magnitude)} N</div><div><small>DIRECTION FROM +x</small>${r.angle===null?'Undefined':fmt(r.angle)+'°'}</div>`;}
for(const id of ['a','b','alpha','beta'])$(id).addEventListener('input',()=>{let v=Number($(id).value);if(!Number.isFinite(v)||$(id).value==='')return;if(id==='a'||id==='b')v=Math.max(0,Math.min(1000,v));else v=Math.max(-360,Math.min(360,v));state[id]=v;render();});for(const id of ['components','parallelogram'])$(id).onchange=render;
$('reset').onclick=()=>{state={a:120,alpha:30,b:90,beta:120};syncInputs();render();};function syncInputs(){Object.entries(state).forEach(([k,v])=>$(k).value=v);}
let drag=null;$('diagram').onpointerdown=e=>{let id=e.target.dataset.force;if(!id)return;drag={id,scale:Number($('diagram').dataset.scale)};$('diagram').setPointerCapture(e.pointerId);};$('diagram').onpointermove=e=>{if(!drag)return;let pt=$('diagram').createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;pt=pt.matrixTransform($('diagram').getScreenCTM().inverse());const x=(pt.x-250)/drag.scale,y=(285-pt.y)/drag.scale;state[drag.id]=Math.round(Math.min(1000,Math.hypot(x,y)));state[drag.id==='a'?'alpha':'beta']=Math.round((Math.atan2(y,x)*180/Math.PI+360)%360);syncInputs();render();};$('diagram').onpointerup=$('diagram').onpointercancel=()=>drag=null;
function readCount(){try{return Number(localStorage.getItem('staticsSolved'))||0;}catch{return 0;}}$('count').textContent=readCount();
function renderPractice(){hintLevel=0;solved=false;$('problem').innerHTML=`Force <strong class=f1>A</strong> is <strong>${practice.a} N</strong> at <strong>${practice.alpha}° from +x</strong>. Force <strong class=f2>B</strong> is <strong>${practice.b} N</strong> at <strong>${practice.beta}° from +x</strong>. Find the <strong>resultant magnitude</strong> and its <strong>counterclockwise direction from +x (0–360°)</strong>. Round to the <strong>nearest whole N and degree</strong>.`;$('practiceSvg').innerHTML=`<svg viewBox="0 0 600 440" role="img" aria-label="Practice force diagram">${diagram(practice,false).out}</svg>`;$('feedback').textContent='';$('hintText').textContent='';$('practiceSolution').hidden=true;$('answerMagnitude').value='';$('answerAngle').value='';}
$('check').onclick=()=>{if(!$('answerMagnitude').value||!$('answerAngle').value){$('feedback').textContent='Enter both magnitude and direction first.';return;}const r=M.resultant(practice.a,practice.alpha,practice.b,practice.beta),v=Number($('answerMagnitude').value),a=Number($('answerAngle').value),diff=Math.abs(((a-r.angle+540)%360+360)%360-180);if(v>=0&&Math.abs(v-r.magnitude)<=1&&diff<=1){$('feedback').textContent='Correct. You combined the signed components and found the right direction.';if(!solved){solved=true;let count=readCount()+1;try{localStorage.setItem('staticsSolved',count);}catch{}$('count').textContent=count;}}else if(Math.abs(v-(practice.a+practice.b))<1){$('feedback').textContent='You may have added magnitudes. Forces at different angles must be added as vectors.';}else $('feedback').textContent='Check each component’s sign, then check the quadrant of your direction. Answers within 1 N and 1° are accepted.';};
$('hint').onclick=()=>{let hints=['Sketch both forces from the same origin. Which components point in a negative direction?','Use Aₓ = A cos α and Aᵧ = A sin α; do the same for B.','Add components: Rₓ = Aₓ + Bₓ and Rᵧ = Aᵧ + Bᵧ. Then use R = √(Rₓ² + Rᵧ²) and check the direction quadrant.'];$('hintText').textContent=hints[Math.min(hintLevel++,2)];};$('reveal').onclick=()=>{$('practiceSolution').innerHTML=solution(practice);$('practiceSolution').hidden=false;};$('newProblem').onclick=()=>{practice={a:20+20*Math.ceil(Math.random()*8),b:20+20*Math.ceil(Math.random()*8),alpha:[0,30,45,60][Math.floor(Math.random()*4)],beta:[90,120,135,150][Math.floor(Math.random()*4)]};renderPractice();};
function renderReference(){
 const square=x=>'<msup>'+x+mn(2)+'</msup>',root=x=>'<msqrt><mrow>'+x+'</mrow></msqrt>';
 const formulas={
 position:taggedVector('r','AB','displacement')+mo('=')+taggedVector('r','B','positionB')+mo('−')+taggedVector('r','A','positionA')+mo('=')+mo('(')+mi('xB')+mo('−')+mi('xA')+mo(')')+mi('i')+mo('+')+mo('(')+mi('yB')+mo('−')+mi('yA')+mo(')')+mi('j')+mo('+')+mo('(')+mi('zB')+mo('−')+mi('zA')+mo(')')+mi('k'),
 direction3D:mi('cos','cos3D')+mi('α','alpha3D')+mo('=')+sub('u','x')+mo(' , ')+mi('cos','cos3D')+mi('β','beta3D')+mo('=')+sub('u','y')+mo(' , ')+mi('cos','cos3D')+mi('γ','gamma3D')+mo('=')+sub('u','z'),
 components:sub('F','x')+mo('=')+mi('F')+mi('cos')+mi('θ','thetaForce')+mo(' , ')+sub('F','y')+mo('=')+mi('F')+mi('sin')+mi('θ','thetaForce'),
 cartesian:vector('F','Fvector')+mo('=')+sub('F','x')+mi('i')+mo('+')+sub('F','y')+mi('j')+mo('+')+sub('F','z')+mi('k'),
 sum:sub('R','x')+mo('=')+sub('A','x')+mo('+')+sub('B','x')+mo(' , ')+sub('R','y')+mo('=')+sub('A','y')+mo('+')+sub('B','y'),
 magnitude:mi('R')+mo('=')+root(square(sub('R','x'))+mo('+')+square(sub('R','y'))+mo('+')+square(sub('R','z'))),
 direction:mi('θ','thetaResult')+mo('=')+mi('atan2')+mo('(')+sub('R','y')+mo(',')+sub('R','x')+mo(')'),
 parallelogram:mi('R')+mo('=')+root(square(mi('A'))+mo('+')+square(mi('B'))+mo('+')+mn(2)+mi('A')+mi('B')+mi('cos')+mi('φ','phi')),
 unit:vector('u','uvector')+mo('=')+fraction(vector('r','rvector'),symbolMarkup('|r|','rmag','<mrow><mo>|</mo><mi>r</mi><mo>|</mo></mrow>')),
 directed:vector('F','Fvector')+mo('=')+mi('F')+vector('u','uvector')
 };
 $('equations').innerHTML='<p class="symbol-help">Tap an <strong>underlined variable</strong> in any equation. The buttons below each equation offer the same explanations for keyboard and touch use.</p>'+Learning.cards.map(c=>`<article class="equation-card" data-equation="${c.title}"><h3>${c.title}</h3><div class="math">${math(Learning.formulas?.[c.body]?.()||formulas[c.body])}</div><div class="symbol-buttons">${c.symbols.map(key=>`<button data-symbol="${key}">${Learning.symbols[key][0].split(' · ')[0]}</button>`).join('')}</div><dl class="equation-guidance"><div><dt>Use it to</dt><dd>${c.use}</dd></div><div><dt>Information needed</dt><dd>${c.need}</dd></div><div><dt>Conditions & checks</dt><dd>${c.condition}</dd></div><div><dt>Example</dt><dd>${c.example}</dd></div></dl></article>`).join('');
}
$('print').onclick=()=>window.print();
let mode='DEG',ans=0;const buttons=[['sin','sin('],['cos','cos('],['tan','tan('],['^','^'],['√','sqrt('],['sin⁻¹','asin('],['cos⁻¹','acos('],['tan⁻¹','atan('],['(','('],[')',')'],['7','7'],['8','8'],['9','9'],['÷','/'],['log','log('],['4','4'],['5','5'],['6','6'],['×','*'],['ln','ln('],['1','1'],['2','2'],['3','3'],['−','-'],['π','pi'],['0','0'],['.','.'],['(−)','-'],['+','+'],['ENTER','enter'],['Ans','ans'],['x²','^2'],['abs','abs('],['EE','e'],[',',',']];$('keys').innerHTML=buttons.map(([label,value])=>`<button data-key="${value}" class="${value==='enter'?'enter':/^\d$/.test(value)?'digit':''}">${label}</button>`).join('');
function preview(){try{$('mathPreview').innerHTML=math(M.markup(M.parse($('expression').value)));}catch{$('mathPreview').textContent=$('expression').value?'Complete the expression to preview it.':'';}}
function calculate(){try{let expression=$('expression').value;ans=M.evaluate(M.parse(expression),mode,ans);$('calcAnswer').textContent=Number(ans.toPrecision(12)).toString();$('history').textContent=expression+' = '+$('calcAnswer').textContent;}catch(e){$('calcAnswer').textContent=e.message;}}
$('keys').onclick=e=>{let k=e.target.dataset.key;if(!k)return;if(k==='enter'){calculate();return;}const input=$('expression');input.setRangeText(k,input.selectionStart,input.selectionEnd,'end');input.focus();preview();};$('expression').oninput=preview;$('expression').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();calculate();}};$('mode').onclick=()=>{mode=mode==='DEG'?'RAD':'DEG';$('angleMode').textContent=mode;};$('clear').onclick=()=>{$('expression').value='';$('calcAnswer').textContent='0';$('history').textContent='';preview();};$('backspace').onclick=()=>{const el=$('expression'),start=el.selectionStart,end=el.selectionEnd;el.setRangeText('',start===end?Math.max(0,start-1):start,end,'end');el.focus();preview();};$('calculatorToggle').onclick=()=>{$('calculator').hidden=!$('calculator').hidden;if(!$('calculator').hidden)$('expression').focus();};$('closeCalc').onclick=()=>$('calculator').hidden=true;document.addEventListener('keydown',e=>{if(e.key==='Escape')$('calculator').hidden=true;});render();renderPractice();renderReference();

function explainSymbol(target){
 const info=Learning.symbols[target.dataset.symbol];if(!info)return;
 $('symbolTitle').textContent=info[0];
 $('symbolDescription').textContent=info[1];
 $('symbolContext').textContent='IN THIS EQUATION / '+(target.closest('[data-equation]')?.dataset.equation||'Force-vector lesson');
 $('symbolDialog').showModal();
}
document.addEventListener('click',e=>{const target=e.target.closest('[data-symbol]');if(target)explainSymbol(target);});
document.addEventListener('keydown',e=>{const target=e.target.closest('.symbol-token');if(target&&(e.key==='Enter'||e.key===' ')){e.preventDefault();explainSymbol(target);}});
$('closeSymbol').onclick=()=>$('symbolDialog').close();
$('symbolDialog').addEventListener('click',e=>{if(e.target===$('symbolDialog')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)e.target.close();}});
